private static <T> T checkConversionResult(Class<T> type, Object result) {
    if (type == null) {
        @SuppressWarnings("unchecked")
        T temp = (T) result;
        return temp;
    }
    if (result == null) {
        // If result is null, return null as the result for any type
        return null;
    }
    if (type.isInstance(result)) {
        return type.cast(result);
    }
    // Handle conversion from empty string to null for certain types
    if (result instanceof String && ((String) result).isEmpty()) {
        if (type == String.class) {
            return type.cast(result); // if type is String, return empty string
        }
        return null; // for other types, treat empty string as null
    }
    throw new ConversionException("Unsupported target type: " + type);
}

